#!/usr/bin/env node
// Скрипт заменяет в миграциях тип SERIAL на GENERATED BY DEFAULT AS IDENTITY
// В Prisma известная проблема, что autoincrement() использует устаревший тип SERIAL

import { existsSync, readdirSync, readFileSync, writeFileSync } from 'node:fs';
import { join, resolve } from 'node:path';

const MIGRATIONS_DIR = resolve('prisma/migrations');

const SERIAL_TYPES = {
  smallserial: 'SMALLINT',
  serial2: 'SMALLINT',
  serial: 'INTEGER',
  serial4: 'INTEGER',
  bigserial: 'BIGINT',
  serial8: 'BIGINT',
};

function resolveMigrationDir(explicitPath) {
  if (explicitPath) {
    const dir = resolve(explicitPath);
    if (!existsSync(join(dir, 'migration.sql'))) {
      throw new Error(`migration.sql not found in ${dir}`);
    }
    return dir;
  }

  if (!existsSync(MIGRATIONS_DIR)) {
    throw new Error(
      `Migrations directory not found: ${MIGRATIONS_DIR}\n` +
        'Run `prisma migrate dev --create-only` first to create a migration.',
    );
  }

  const dirs = readdirSync(MIGRATIONS_DIR, { withFileTypes: true })
    .filter((entry) => entry.isDirectory())
    .map((entry) => entry.name)
    .sort();

  if (dirs.length === 0) {
    throw new Error(`No migrations found in ${MIGRATIONS_DIR}`);
  }
  return join(MIGRATIONS_DIR, dirs.at(-1));
}

const file = join(resolveMigrationDir(process.argv[2]), 'migration.sql');
const sql = readFileSync(file, 'utf8');

const pattern =
  /"([^"]+)"\s+(SMALLSERIAL|SERIAL2|SERIAL|SERIAL4|BIGSERIAL|SERIAL8)(\s+NOT NULL)?/gi;

let count = 0;
const patched = sql.replace(pattern, (_match, column, type) => {
  count += 1;
  const baseType = SERIAL_TYPES[type.toLowerCase()];
  return `"${column}" ${baseType} GENERATED BY DEFAULT AS IDENTITY NOT NULL`;
});

if (count === 0) {
  console.log(`No SERIAL columns found in ${file} — nothing to do.`);
} else {
  writeFileSync(file, patched);
  console.log(
    `Rewrote ${count} SERIAL column(s) to GENERATED BY DEFAULT AS IDENTITY in ${file}`,
  );
}
